        public IConfigTable CreateTable(IList rows)
        {
            return new AllTypes10kConfigTable((IEnumerable<AllTypes10kConfig>)rows);
        }

        public void Write(Stream output, IList rows)
        {
            if (!output.CanSeek)
            {
                using var buffer = new MemoryStream();
                Write(buffer, rows);
                buffer.Position = 0;
                buffer.CopyTo(output);
                return;
            }

            using var writer = new BinaryWriter(output, Encoding.UTF8, true);
            BinaryFormat.WriteHeader(writer, TableName, SchemaHash, rows.Count);
            WriteTypes(writer);
            long[] locations = ArrayPool<long>.Shared.Rent(rows.Count);
            try
            {
                for (int i = 0; i < rows.Count; i++)
                {
                    var row = (AllTypes10kConfig)rows[i]!;
                    Write46(writer, row.@Id, 0);
                    writer.Write(row.@Id);
                    locations[i] = output.Position;
                    writer.Write(0);
                    writer.Write(0); // 相对行数据区的偏移、长度
                }

                long dataStart = output.Position;
                for (int i = 0; i < rows.Count; i++)
                {
                    long start = output.Position;
                    WriteRow(writer, (AllTypes10kConfig)rows[i]!);
                    long end = output.Position;
                    output.Position = locations[i];
                    writer.Write(checked((int)(start - dataStart)));
                    writer.Write(checked((int)(end - start)));
                    output.Position = end;
                }
            }
            finally
            {
                ArrayPool<long>.Shared.Return(locations);
            }
        }

