        public IConfigRowReader Open(byte[] bytes)
        {
            using var input = new MemoryStream(bytes, false);
            using var header = new BinaryReader(input, Encoding.UTF8, true);
            int count = BinaryFormat.ReadHeader(header, TableName, SchemaHash);
            ConfigReadContext context = ReadTypes(header);
            var decoder = new RowDecoder(context);
            return new ConfigRowReader<AllTypes10kConfig, int>(bytes,
                header,
                count,
                decoder.ReadKey,
                decoder.Read,
                s_selectKey,
                s_selectId);
        }

        // 显式保存本次读取的上下文，避免匿名函数捕获局部变量。
        private sealed class RowDecoder
        {
            private readonly ConfigReadContext _context;
            public RowDecoder(ConfigReadContext context)
            {
                _context = context;
            }

            public int ReadKey(BinaryReader reader)
            {
                ConfigReadContext context = _context;
                return Read46(reader, context, 0);
            }

            public AllTypes10kConfig Read(BinaryReader reader)
            {
                return ReadRow(reader, _context.ForRow());
            }
        }

